CREATE TABLE IF NOT EXISTS learner_states (user_id UUID PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, state JSONB NOT NULL DEFAULT '{}', updated_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS learner_concepts (user_id UUID, concept TEXT, mastery REAL DEFAULT 0, confidence REAL DEFAULT 0, evidence_count INT DEFAULT 0, PRIMARY KEY(user_id,concept)); CREATE TABLE IF NOT EXISTS learner_gaps (id UUID PRIMARY KEY, user_id UUID, concept TEXT, confidence REAL, source TEXT, created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS misconceptions (id UUID PRIMARY KEY, user_id UUID, concept TEXT, description TEXT, confidence REAL, status TEXT, first_observed TIMESTAMPTZ DEFAULT now(), last_observed TIMESTAMPTZ DEFAULT now(), repair_attempts INT DEFAULT 0);
